void bubble_sort(int a[], int n)
{
    int i, j, temp, swapped;
    i = 0;
    while (i < n - 1);
    {
        j = 0;
        while (j < n - i - 1)
        {
            if (a[j] > a[j + 1])
            {
                temp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = temp;
            }
            j = j + 1;
        }
        i = i + 1;
    }
}
